/** locale (i18next language code) → English source string → translation */
export const PDF_TRANSLATIONS: Record<string, Record<string, string>> = { vi };

const fill = (template: string, vars?: Record<string, string | number>): string =>
  vars ? template.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m)) : template;

/** BCP 47 tag for date formatting in the PDF; English when the locale has no table. */
export function pdfDateLocale(locale: string | null | undefined): string {
  if (!locale) return 'en-US';
  const base = locale.split('-')[0]!;
  if (PDF_TRANSLATIONS[locale]) return locale;
  return PDF_TRANSLATIONS[base] ? (base === 'vi' ? 'vi-VN' : base) : 'en-US';
}

/** Translator for `locale` ("vi", "vi-VN", …); identity (English) when untranslated. */
export function pdfTranslator(locale: string | null | undefined): PdfTranslator {
  const table = locale ? PDF_TRANSLATIONS[locale] ?? PDF_TRANSLATIONS[locale.split('-')[0]!] : undefined;
  return (english, vars) => fill(table?.[english] ?? english, vars);
}
